---__int
function BattleHelperVo:__init()
    self.id = -1
    self.cardId = nil           --卡牌id
    self.positon = nil          --队伍中的位置/可能会用到
    self.cardVo = nil           --卡牌的配置数据
    self.fettersId = 0           --羁绊id
    self.fettersCardId = 0           --羁绊卡牌id

    self.star = 0             --角色星级
    self.cardLevel = nil        --角色等级
    self.locked = 0             --是否锁定状态
    self.cardSkin = 0             --皮肤id

    --三个技能等级
    self.finalSkillLevel = 1    --大招技能等级
    self.openAbility = nil      --开放天赋（1~6对应解锁天赋数量）

    --六件装备
    self.equipment1 = {}
    self.equipment2 = {}
    self.equipment3 = {}
    self.equipment4 = {}
    self.equipment5 = {}
    self.equipment6 = {}

    self.status = nil     --状态
end

--填充卡牌id 和数据
function BattleHelperVo:FillCardId(cardId)
    if not cardId then return end
    self.cardId = checkNumber(cardId)
    self.cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardId)  --CfUtils.GetCfVo(AutoIds.IdSetting108, "CardVo", cardId)
end

--填充卡牌在队伍中的站位
function BattleHelperVo:FillTeamPosition(pos)
    if not pos then return end
    self.positon = checkNumber(pos)
end

--[[
    @desc: 填充基本信息
    author:{author}
    time:2020-07-13 14:37:58
    --@star: 星级
	--@cardLevel: 等级
    @return:
]]
---@param basicsInfoVo BattleHelperAttrVo 机器人属性表 数据
---@param index number 机器人阵容下标
---@param cardSkin number 机器人上阵 皮肤id 
function BattleHelperVo:FillBasicsInfo(basicsInfoVo, index, cardSkin)
    local starLevelV    = CfUtils.Split(basicsInfoVo.petStar)
    local advLv         = CfUtils.Split(basicsInfoVo.petRare) --- 进阶等级
    local levelV        = CfUtils.Split(basicsInfoVo.petLv)
    local petWeaponV    = CfUtils.Split(basicsInfoVo.petWeapon)    --专武

    self.star           = checkNumber(starLevelV[index])
    self.cardLevel      = checkNumber(levelV[index])
    self.advanceLevel   = checkNumber(advLv[index])
    self.cardSkin       = checkNumber(cardSkin)
    self.weaponUnlocked = checkNumber(petWeaponV[index])
    
    local finalSkillLv, buffSkillLv = CardProgressionSkillUtils.GetFinalSkillLvAndBuffLv(self.cardId, self.star)
    self.finalSkillLevel = finalSkillLv
    self.awakeningLevel = buffSkillLv

    --- 【cardSkin】字段为当前阵容中的机器人的 穿戴皮肤 ，和战力属性无关
    --- 默认皮肤等级
    local skin1Lv       = basicsInfoVo.skin1Lv
    --- 99皮肤等级
    local skin2Lv       = basicsInfoVo.skin2Lv

    ---@type CardConfMgr
    local cardConfMgr = CardConfMgr:GetInstance()
    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(self.cardId)
    self.cardSkinId2Lv  = {
        [cardVo.defaultSkin] = checkNumber(skin1Lv[index])
    }
    local rare = cardConfMgr:GetCardRareByCardId(self.cardId, self.advanceLevel)
    if rare >= Constants.RareType.UR and cardConfMgr:GetCardSkinBySkinId(cardVo.urSkin, true) then
        self.cardSkinId2Lv[cardVo.urSkin] = checkNumber(skin2Lv[index])
    end

end

