--[[
    @desc: 填充身上的六个装备      ！！！副属性需要去读一个副属性表 如果不适用就再重写一个填充装备的方法
    author:{author}
    time:2020-07-13 14:24:08
    --@idData: array 装备id 
    --@levelData: array 装备等级
    --@secondAttrIdData: array 副属性
    @return:
]]
function BattleHelperVo:FillEquip(equipGoodsIds)
    if equipGoodsIds == nil then
        return
    end

    ---装备
    for index, equipGoodsId in ipairs(equipGoodsIds) do
        equipGoodsId = checkNumber(equipGoodsId)
        self:FillEquipByEquipGoodsId(equipGoodsId, index)
    end

end

function BattleHelperVo:FillEquipByEquipGoodsId(equipGoodsId, index)
    if equipGoodsId <= 0 then
        return
    end
    local idType = GoodsUtils.GetIdType(equipGoodsId)
    if idType == Constants.IDType.GoodsCommission then
        self[string.format("equipment%s", index)] = EquipUtils.GenerateCustomEquip(equipGoodsId)
    elseif idType == Constants.IDType.Equipment then
        self[string.format("equipment%s", index)] = EquipUtils.GenerateEquip(equipGoodsId)
    end
end

function BattleHelperVo:__delete()
    self.id = nil           --助战id
    self.cardId = nil      --
    self.name = nil
    self.star = nil           --角色星级
    self.equipId = nil    --图芯卡ID
    self.starNum = nil    --图芯卡星级范围（1随机1~3,2随机3~5）整套装备星级统一
    self.starSkill = nil    --大招技能等级
    self.openAbility = nil    --开放天赋（1~6对应解锁天赋数量）
    self.status = nil     --状态
    self.cardLevel = nil
    self.awakeningLevel = nil
    self.strengthenLevel = nil
    self.advancedSkillLevel = nil
    self.generalSkillLevel = nil
    self.finalSkillLevel = nil
end

return BattleHelperVo